mapper.select:
select id, user_id, (select userName from user where id = user_id) as userName, (select head from user where id = user_id) as head, item_name, type, item_desc, location, phone, create_time, image1, status, is_top from lost_item
and item_name like concat('%',#{itemName},'%')
and type = #{type}
and create_time >= #{createTimeStart}
and create_time <= #{createTimeEnd}
and status = #{status}
order by is_top desc, create_time desc
